static void permutSR(LinkedList<Integer>L1,
                     LinkedList<Integer>L2,
                     int r){

    if(L1.size()==r){
        System.out.println(L1);
        return;
    }

    for(int k=0;k<L2.size();k++)
        if(!L1.contains(L2.get(k))){
            L1.add(L2.get(k));
            permutSR(L1,L2,r);
            L1.removeLast();
        }
}
